+import { createClient } from 'redis';
+import { config } from './config/index.js';
+
+let redisClient;
+let redisConnectPromise;
+
+function getRedisClient(redisUrl) {
+  if (!redisClient) {
+    redisClient = createClient({ url: redisUrl });
+    redisClient.on('error', (error) => {
+      console.error('rate limit redis error', error);
+    });
+  }
+
+  if (!redisConnectPromise) {
+    redisConnectPromise = redisClient.connect().catch((error) => {
+      console.error('failed to connect rate limit redis client', error);
+      redisConnectPromise = null;
+    });
+  }
+
+  return redisClient;
+}
+
+function createRedisStore(redisUrl) {
+  const client = getRedisClient(redisUrl);
+
+  return new RedisStore({
+    sendCommand: (...args) => client.sendCommand(args),
+  });
+}
+
+export function createRateLimiter(overrides = {}) {
+  const redisUrl = overrides.redisUrl ?? config.redisUrl;
+  const limiterConfig = {
+    windowMs: overrides.windowMs ?? config.rateLimitWindowMs,
+    limit: overrides.limit ?? config.rateLimitLimit,
+    standardHeaders: 'draft-8',
+    legacyHeaders: false,
+    passOnStoreError: true,
+    handler: (req, res) => {
+      res.status(429).json({ error: 'too many requests' });
+    },
+  };
+
+  if (redisUrl) {
+    limiterConfig.store = createRedisStore(redisUrl);
+  }
+
+  return rateLimit(limiterConfig);
+}
